// RFC 9457 Problem Details：统一错误响应体结构（application/problem+json）
const PROBLEM_BASE = 'https://api.example.com/problems/';
const TITLES = {
  400: 'Bad Request', 401: 'Unauthorized', 403: 'Forbidden', 404: 'Not Found',
  405: 'Method Not Allowed', 409: 'Conflict', 415: 'Unsupported Media Type',
  422: 'Unprocessable Content', 429: 'Too Many Requests',
  500: 'Internal Server Error', 503: 'Service Unavailable',
};

function problem(spec) {
  const doc = {
    type: spec.code ? PROBLEM_BASE + spec.code : 'about:blank',
    title: spec.title || TITLES[spec.status] || 'Error',
    status: spec.status,
    detail: spec.detail,
    instance: spec.instance,
  };
  // 扩展成员：字段级校验错误（约定用 errors 数组 + JSON Pointer）
  if (Array.isArray(spec.errors) && spec.errors.length > 0) {
    doc.errors = spec.errors.map(function (e) { return { pointer: e.pointer, detail: e.detail }; });
  }
  if (spec.retryAfterSec !== undefined) doc.retryAfterSec = spec.retryAfterSec;
  return doc;
}

const responses = [
  problem({
    status: 422, code: 'validation-failed', instance: '/articles',
    detail: 'The request body failed schema validation.',
    errors: [
      { pointer: '/title', detail: 'must be a non-empty string of at most 40 characters' },
      { pointer: '/status', detail: 'must be one of draft, published' },
    ],
  }),
  problem({
    status: 404, code: 'article-not-found', instance: '/articles/999',
    detail: 'Article 999 does not exist.',
  }),
  problem({
    status: 409, code: 'slug-conflict', instance: '/articles',
    detail: 'An article with the same slug already exists.',
  }),
  problem({
    status: 429, code: 'rate-limit-exceeded', instance: '/articles',
    detail: 'Request quota exceeded for this client.', retryAfterSec: 30,
  }),
  problem({ status: 503, instance: '/health', detail: 'The database is unreachable.' }),
];

const CORE = ['type', 'title', 'status', 'detail', 'instance'];
for (let i = 0; i < responses.length; i++) {
  const p = responses[i];
  console.log('response#' + i);
  console.log('  HTTP/1.1 ' + p.status + ' ' + p.title);
  console.log('  Content-Type: application/problem+json');
  console.log('  Retry-After: ' + (p.retryAfterSec === undefined ? '-' : p.retryAfterSec));
  console.log('  body=' + JSON.stringify(p));
}

const checks = responses.map(function (p) {
  const coreOk = CORE.every(function (k) { return Object.prototype.hasOwnProperty.call(p, k); });
  const typeOk = p.type === 'about:blank' || /^https?:\/\//.test(p.type);
  const ext = Object.keys(p).filter(function (k) { return CORE.indexOf(k) === -1; });
  const extNoClash = ext.every(function (k) { return CORE.indexOf(k) === -1; });
  return '  status=' + p.status + ' core_fields_ok=' + coreOk + ' type_is_uri_reference=' + typeOk
    + ' extension_members=' + JSON.stringify(ext) + ' no_core_clash=' + extNoClash;
});
console.log('structure_checks:');
checks.forEach(function (c) { console.log(c); });
console.log('all_core_fields_ok=' + responses.every(function (p) {
  return CORE.every(function (k) { return Object.prototype.hasOwnProperty.call(p, k); });
}));
